mapper.select:
SELECT m.meeting_id AS meetingId, m.title, m.status, u.nickname AS hostNickname, COUNT(mp.participant_id) AS participantCount, m.created_at AS createdAt FROM meetings m JOIN users u ON u.user_id = m.host_user_id LEFT JOIN meeting_participants mp ON mp.meeting_id = m.meeting_id
WHERE m.title LIKE CONCAT('%', #{query}, '%') OR u.nickname LIKE CONCAT('%', #{query}, '%')
GROUP BY m.meeting_id, m.title, m.status, u.nickname, m.created_at ORDER BY m.created_at DESC, m.meeting_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM chat_messages
WHERE meeting_id = #{meetingId}
